760	const APPLICATION_BATCH_KEYS = Object.freeze(["action", "batch"]);
761	const APPLICATION_BATCH_PAYLOAD_KEYS = Object.freeze(["entries", "version"]);
762	
763	function detachedRoomOperation(value: unknown): Readonly<Record<string, unknown>> | undefined {
764		try {
765			const decoded = decodeCanonical(encodeCanonical(value));
766			if (decoded === null || typeof decoded !== "object" || Array.isArray(decoded)) return undefined;
767			return Object.freeze({ ...(decoded as Record<string, unknown>) });
768		} catch {
769			return undefined;
770		}
771	}
772	
773	function exactRecord(value: unknown, expectedKeys: readonly string[]): Readonly<Record<string, unknown>> | undefined {
774		if (value === null || typeof value !== "object" || Array.isArray(value)) return undefined;
775		const prototype = Object.getPrototypeOf(value);
776		if (prototype !== null && prototype !== Object.prototype) return undefined;
777		const keys = Reflect.ownKeys(value);
778		if (
779			keys.length !== expectedKeys.length ||
780			keys.some((key) => typeof key !== "string" || !expectedKeys.includes(key))
781		) {
782			return undefined;
783		}
784		const output: Record<string, unknown> = {};
785		for (const key of expectedKeys) {
786			const descriptor = Object.getOwnPropertyDescriptor(value, key);
787			if (descriptor === undefined || descriptor.enumerable !== true || !("value" in descriptor)) return undefined;
788			output[key] = descriptor.value;
789		}
790		return Object.freeze(output);
791	}
792	
793	const ROOM_HEAD_KEYS = Object.freeze(["currentAnchorDigest", "epoch", "objectId"]);
794	const ROOM_HEAD_STATE_KEYS = Object.freeze(["pending", "stable"]);
795	const ROOM_HEAD_PENDING_KEYS = Object.freeze(["next", "previous"]);
796	const ROOM_HEAD_INITIALIZATION_KEYS = Object.freeze(["kind"]);
797	const ROOM_HEAD_MIGRATION_KEYS = Object.freeze(["head", "kind"]);
798	const ROOM_HEAD_RESULT_FAILURE_KEYS = Object.freeze(["ok", "reason"]);
799	const ROOM_HEAD_RESULT_SUCCESS_KEYS = Object.freeze(["ok", "state"]);
800	const LOWER_HEX_256 = /^[0-9a-f]{64}$/u;
801	
802	function roomHeadFailure(code: string): never {
803		throw new TypeError(code);
804	}
805	
806	function captureRoomHead(value: unknown): V3RoomHead | undefined {
807		const record = exactRecord(value, ROOM_HEAD_KEYS);
808		return record !== undefined &&
809			typeof record.currentAnchorDigest === "string" &&
810			LOWER_HEX_256.test(record.currentAnchorDigest) &&
811			Number.isSafeInteger(record.epoch) &&
812			(record.epoch as number) >= 0 &&
813			typeof record.objectId === "string" &&
814			record.objectId.length > 0
815			? Object.freeze({
816					currentAnchorDigest: record.currentAnchorDigest,
817					epoch: record.epoch as number,
818					objectId: record.objectId,
819				})
820			: undefined;
821	}
822	
823	function sameRoomHead(left: V3RoomHead, right: V3RoomHead): boolean {
824		return (
825			left.currentAnchorDigest === right.currentAnchorDigest &&
826			left.epoch === right.epoch &&
827			left.objectId === right.objectId
828		);
829	}
830	
831	function captureRoomHeadState(value: unknown, scope: V3RoomHeadScope): V3RoomHeadState | undefined {
832		const record = exactRecord(value, ROOM_HEAD_STATE_KEYS);
833		const stable = captureRoomHead(record?.stable);
834		if (
835			record === undefined ||
836			stable === undefined ||
837			stable.objectId !== scope.objectId ||
838			(stable.epoch === 0 && stable.currentAnchorDigest !== scope.pinnedGenesisAnchorDigest)
839		) {
840			return undefined;
841		}
842		if (record.pending === null) return Object.freeze({ pending: null, stable });
843		const pending = exactRecord(record.pending, ROOM_HEAD_PENDING_KEYS);
844		const previous = captureRoomHead(pending?.previous);
845		const next = captureRoomHead(pending?.next);
846		return pending !== undefined &&
847			previous !== undefined &&
848			next !== undefined &&
849			sameRoomHead(previous, stable) &&
850			next.objectId === scope.objectId &&
