function expectedRoomHeadFromDescriptor(descriptor: Readonly<Record<string, unknown>>): V3RoomHead {
	return (
		captureRoomHead({
			currentAnchorDigest: descriptor.anchorDigest,
			epoch: descriptor.epoch,
