275			return Reflect.get(acceptedOperation.operation, "action") === "join" && typeof peerId === "string"
276				? [{ author: acceptedOperation.author, peerId }]
277				: [];
278		});
279		return Object.freeze({
280			acceptedDigests: Object.freeze(
281				operations
282					.filter(({ operation }) => Reflect.get(operation, "action") !== "projection-hidden")
283					.map(({ vertexDigest }) => vertexDigest)
284			),
285			transportPeerAuthors: Object.freeze(transportPeerAuthors),
